begin;
update public.questions set subject = 'Science & Technology', topic = 'Astronomy & Earth Science', type = 'mcq', difficulty = 'medium', body = 'A planet orbits a red dwarf, a star much cooler and dimmer than the Sun. For the planet to have liquid water on its surface, compared with the Earth''s distance from the Sun, it would have to orbit:', body_hi = 'एक ग्रह एक लाल बौने तारे की परिक्रमा करता है, जो सूर्य से बहुत ठंडा और मंद तारा है। ग्रह की सतह पर द्रव जल होने के लिए, पृथ्वी की सूर्य से दूरी की तुलना में, उसे परिक्रमा करनी होगी:', explanation = 'A dim star warms its surroundings less, so the ''habitable'' or Goldilocks zone -- where a planet''s surface is neither too hot nor too cold for liquid water -- lies close in; for many red dwarfs it is well inside the distance of Mercury from the Sun, as for the planets of TRAPPIST-1. So close in, a planet is likely to be tidally locked, with one side always facing the star, and exposed to strong flares -- reasons why being in the zone does not guarantee life. Venus lies near the inner edge of the Sun''s zone.', explanation_hi = 'मंद तारा अपने आसपास को कम गर्म करता है, इसलिए ''आवासयोग्य'' या गोल्डीलॉक्स क्षेत्र, जहाँ ग्रह की सतह द्रव जल के लिए न बहुत गर्म हो न बहुत ठंडी, पास में होता है; कई लाल बौनों के लिए यह सूर्य से बुध की दूरी से भी काफ़ी भीतर है, जैसे TRAPPIST-1 के ग्रहों के लिए। इतने पास ग्रह के ज्वारीय रूप से बँधे होने की संभावना है, यानी उसका एक ही भाग सदा तारे की ओर रहे, और वह तीव्र ज्वालाओं के संपर्क में रहता है; इसीलिए क्षेत्र में होना जीवन की गारंटी नहीं है। शुक्र सूर्य के क्षेत्र के भीतरी किनारे के पास है।', concept_group_id = 'as-goldilocks-zone', source_citation = 'NASA -- Science (solar system, universe and exoplanet pages).', question_data = '{"craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "much farther from its star, to escape its stronger radiation", "body_hi": "अपने तारे से बहुत दूर, ताकि उसके अधिक तीव्र विकिरण से बच सके", "isCorrect": false}, {"id": "b", "body": "at the same distance as the Earth, since water''s freezing and boiling points are fixed", "body_hi": "पृथ्वी जितनी ही दूरी पर, क्योंकि जल के जमने और उबलने के बिंदु निश्चित हैं", "isCorrect": false}, {"id": "c", "body": "much closer to its star than the Earth is to the Sun", "body_hi": "अपने तारे से उतनी दूरी की तुलना में बहुत पास जितनी पृथ्वी सूर्य से है", "isCorrect": true}, {"id": "d", "body": "at any distance at all, since a red dwarf gives out no heat", "body_hi": "किसी भी दूरी पर, क्योंकि लाल बौना तारा कोई ऊष्मा नहीं देता", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'as-goldilocks-zone' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Astronomy & Earth Science', type = 'mcq', difficulty = 'medium', body = 'Galaxy A is twice as far from us as galaxy B. According to Hubble''s law, galaxy A is:', body_hi = 'आकाशगंगा A हमसे आकाशगंगा B की तुलना में दोगुनी दूर है। हबल के नियम के अनुसार आकाशगंगा A:', explanation = 'Hubble''s law says that a galaxy''s speed of recession is proportional to its distance: v = H0 x d, with the Hubble constant H0 about 70 km per second for every megaparsec. Doubling the distance doubles the speed -- the pattern expected if space itself is expanding evenly, which is why the constant is read as the rate of expansion of the universe. Different methods give values that differ by several per cent, the unresolved ''Hubble tension''. Only a few nearby galaxies, such as Andromeda, held close by gravity, are approaching us.', explanation_hi = 'हबल का नियम कहता है कि किसी आकाशगंगा के दूर जाने की गति उसकी दूरी के अनुपात में होती है: v = H0 x d, जहाँ हबल स्थिरांक H0 प्रति मेगापारसेक लगभग 70 किमी प्रति सेकंड है। दूरी दोगुनी होने पर गति दोगुनी होती है, यही प्रतिरूप अपेक्षित है यदि स्वयं अंतरिक्ष समान रूप से फैल रहा हो; इसीलिए स्थिरांक को ब्रह्मांड के विस्तार की दर माना जाता है। अलग-अलग विधियाँ कुछ प्रतिशत भिन्न मान देती हैं, यही अनसुलझा ''हबल तनाव'' है। केवल एंड्रोमेडा जैसी कुछ पास की आकाशगंगाएँ, जो गुरुत्व से पास बँधी हैं, हमारी ओर आ रही हैं।', concept_group_id = 'as-hubble-constant', source_citation = 'NCERT Class XI, Fundamentals of Physical Geography (The Origin and Evolution of the Earth); NASA.', question_data = '{"craft": "application"}'::jsonb, options = '[{"id": "a", "body": "moving away from us about twice as fast as B", "body_hi": "B की तुलना में लगभग दोगुनी गति से हमसे दूर जा रही है", "isCorrect": true}, {"id": "b", "body": "moving away from us at the same speed as B, since all galaxies recede alike", "body_hi": "B जितनी ही गति से हमसे दूर जा रही है, क्योंकि सभी आकाशगंगाएँ एक समान दूर जाती हैं", "isCorrect": false}, {"id": "c", "body": "moving away from us at half the speed of B", "body_hi": "B की आधी गति से हमसे दूर जा रही है", "isCorrect": false}, {"id": "d", "body": "moving towards us, while B moves away", "body_hi": "हमारी ओर आ रही है, जबकि B दूर जा रही है", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'as-hubble-constant' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Astronomy & Earth Science', type = 'mcq', difficulty = 'medium', body = 'Jupiter is visibly flattened at its poles and bulges at its equator. The main reason is that:', body_hi = 'बृहस्पति अपने ध्रुवों पर स्पष्ट रूप से चपटा है और विषुवत रेखा पर उभरा हुआ है। इसका मुख्य कारण यह है कि:', explanation = 'Spin flings material outward most strongly at the equator, where the surface moves fastest, so a fluid planet bulges there. Jupiter has the shortest day of any planet, just under 10 hours, and is about 7 per cent wider across the equator than from pole to pole; Saturn, spinning nearly as fast and far less dense, is flatter still. The Earth bulges for the same reason, though much less, since it turns only once a day.', explanation_hi = 'घूर्णन विषुवत रेखा पर, जहाँ सतह सबसे तेज़ चलती है, पदार्थ को सबसे अधिक बाहर की ओर फेंकता है, इसलिए तरल ग्रह वहाँ उभर जाता है। बृहस्पति का दिन सभी ग्रहों में सबसे छोटा, 10 घंटे से कुछ कम, है और वह ध्रुव से ध्रुव की तुलना में विषुवत रेखा पर लगभग 7 प्रतिशत अधिक चौड़ा है; लगभग उतनी ही तेज़ी से घूमने वाला और कहीं कम घना शनि और भी चपटा है। पृथ्वी भी इसी कारण उभरी है, यद्यपि बहुत कम, क्योंकि वह दिन में केवल एक बार घूमती है।', concept_group_id = 'as-shortest-day-jupiter', source_citation = 'NASA -- Science (solar system, universe and exoplanet pages).', question_data = '{"craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "the pull of its many moons draws its poles inwards", "body_hi": "इसके अनेक चंद्रमाओं का खिंचाव इसके ध्रुवों को भीतर खींचता है", "isCorrect": false}, {"id": "b", "body": "the Sun heats its equator far more strongly than its poles", "body_hi": "सूर्य इसकी विषुवत रेखा को ध्रुवों की तुलना में कहीं अधिक गर्म करता है", "isCorrect": false}, {"id": "c", "body": "its strong magnetic field squeezes the planet at the poles", "body_hi": "इसका प्रबल चुंबकीय क्षेत्र ग्रह को ध्रुवों पर दबाता है", "isCorrect": false}, {"id": "d", "body": "it spins very fast, turning once in under ten hours", "body_hi": "यह बहुत तेज़ी से घूमता है, दस घंटे से कम में एक चक्कर पूरा करता है", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'as-shortest-day-jupiter' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Astronomy & Earth Science', type = 'mcq', difficulty = 'medium', body = 'As the Earth goes round the Sun, a nearby star appears to shift slightly against much more distant stars. If a second star shows only half this shift, it is:', body_hi = 'पृथ्वी के सूर्य की परिक्रमा करते समय एक पास का तारा कहीं अधिक दूर के तारों की पृष्ठभूमि में थोड़ा खिसकता दिखता है। यदि एक दूसरा तारा इसका केवल आधा खिसकाव दिखाए, तो वह:', explanation = 'Parallax works like holding up a finger and looking at it with each eye in turn: the nearer the finger, the bigger the jump. A star''s parallax angle is inversely proportional to its distance -- a parallax of one arcsecond defines one parsec -- so half the shift means twice the distance. Because the angles are tiny, the method works only for relatively nearby stars; the Gaia spacecraft has measured parallaxes for over a billion of them. Farther out, astronomers use ''standard candles'' of known brightness.', explanation_hi = 'लंबन ऐसे काम करता है जैसे एक उँगली उठाकर बारी-बारी से हर आँख से देखना: उँगली जितनी पास, उछाल उतना बड़ा। किसी तारे का लंबन कोण उसकी दूरी के व्युत्क्रमानुपाती होता है, एक चाप-सेकंड का लंबन एक पारसेक को परिभाषित करता है, इसलिए आधा खिसकाव दोगुनी दूरी बताता है। कोण बहुत छोटे होने के कारण यह विधि अपेक्षाकृत पास के तारों के लिए ही काम करती है; गाया अंतरिक्ष यान ने एक अरब से अधिक तारों का लंबन मापा है। उससे दूर खगोलविद ज्ञात चमक वाली ''मानक मोमबत्तियों'' का उपयोग करते हैं।', concept_group_id = 'as-stellar-parallax', source_citation = 'NCERT Class XI Physics (Units and Measurement: the parallax method); ESA -- Gaia mission.', question_data = '{"craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "about half as far away as the first star", "body_hi": "पहले तारे से लगभग आधी दूरी पर है", "isCorrect": false}, {"id": "b", "body": "about twice as far away as the first star", "body_hi": "पहले तारे से लगभग दोगुनी दूरी पर है", "isCorrect": true}, {"id": "c", "body": "about as far away, but moving more slowly across the sky", "body_hi": "लगभग उतनी ही दूरी पर है, पर आकाश में धीरे चल रहा है", "isCorrect": false}, {"id": "d", "body": "too far away for its distance ever to be measured from the Earth", "body_hi": "इतना दूर है कि पृथ्वी से उसकी दूरी कभी मापी ही नहीं जा सकती", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'as-stellar-parallax' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Biology, Health & Biotechnology', type = 'mcq', difficulty = 'medium', body = 'Which one of the following diseases is caused by a protozoan and spread by the bite of an insect?', body_hi = 'निम्नलिखित में से कौन-सा रोग एक प्रोटोज़ोआ से होता है और किसी कीट के काटने से फैलता है?', explanation = 'Kala-azar (visceral leishmaniasis) is caused by the protozoan Leishmania donovani and spread by sandflies; in 2023 India met its elimination target of under one case per 10,000 people in every endemic block. Amoebic dysentery is also caused by a protozoan, but it spreads through contaminated food and water; dengue is spread by Aedes mosquitoes but is caused by a virus; and typhoid is a bacterial disease carried in water and food. Malaria, caused by Plasmodium and spread by Anopheles mosquitoes, would also meet both conditions.', explanation_hi = 'काला-अज़ार (आंत्रिक लीशमैनियासिस) प्रोटोज़ोआ लीशमैनिया डोनोवानी से होता है और सैंडफ़्लाई से फैलता है; 2023 में भारत ने हर प्रभावित ब्लॉक में प्रति 10,000 लोगों पर एक से कम मामले का उन्मूलन लक्ष्य पूरा किया। अमीबी पेचिश भी प्रोटोज़ोआ से होती है, पर दूषित भोजन और पानी से फैलती है; डेंगू एडीज़ मच्छरों से फैलता है पर वायरस से होता है; और टाइफ़ाइड पानी और भोजन से फैलने वाला जीवाणु रोग है। प्लाज़्मोडियम से होने वाला और एनोफ़िलीज़ मच्छरों से फैलने वाला मलेरिया भी दोनों शर्तें पूरी करता।', concept_group_id = 'bi-protozoan-disease', source_citation = 'NCERT Class XII Biology (Human Health and Disease); National Center for Vector Borne Diseases Control.', question_data = '{"craft": "precision"}'::jsonb, options = '[{"id": "a", "body": "Dengue", "body_hi": "डेंगू", "isCorrect": false}, {"id": "b", "body": "Typhoid", "body_hi": "टाइफ़ाइड", "isCorrect": false}, {"id": "c", "body": "Kala-azar", "body_hi": "काला-अज़ार", "isCorrect": true}, {"id": "d", "body": "Amoebic dysentery", "body_hi": "अमीबी पेचिश", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'bi-protozoan-disease' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Biology, Health & Biotechnology', type = 'mcq', difficulty = 'medium', body = 'Which one of the following kinds of vaccine is generally NOT given to people whose immune systems are severely weakened?', body_hi = 'निम्नलिखित में से किस प्रकार का टीका सामान्यतः उन लोगों को नहीं दिया जाता जिनकी प्रतिरक्षा प्रणाली गंभीर रूप से कमज़ोर हो?', explanation = 'A live attenuated vaccine, such as the oral polio vaccine or the MMR vaccine, contains a weakened form of the pathogen that can still multiply; in a person whose immune system cannot control it -- for example during cancer chemotherapy or advanced HIV infection -- it may cause disease. Inactivated vaccines use killed pathogens, toxoids use inactivated toxins (as against tetanus), and non-replicating viral vector vaccines such as Covishield use a harmless virus that cannot multiply to carry the gene for a target protein; none of these can cause the infection.', explanation_hi = 'जीवित क्षीणीकृत टीके, जैसे मुख से दिया जाने वाला पोलियो टीका या MMR टीका, में रोगाणु का एक कमज़ोर रूप होता है जो अब भी गुणन कर सकता है; जिस व्यक्ति की प्रतिरक्षा प्रणाली उसे नियंत्रित न कर सके, जैसे कैंसर कीमोथेरेपी या उन्नत HIV संक्रमण के दौरान, उसमें यह रोग पैदा कर सकता है। निष्क्रिय टीके मारे गए रोगाणुओं का, टॉक्सॉइड निष्क्रिय विषों का (जैसे टिटनेस के विरुद्ध), और कोविशील्ड जैसे प्रतिकृति न बनाने वाले वायरल वेक्टर टीके लक्ष्य प्रोटीन का जीन ले जाने के लिए गुणन न कर सकने वाले हानिरहित वायरस का उपयोग करते हैं; इनमें से कोई भी संक्रमण पैदा नहीं कर सकता।', concept_group_id = 'bi-viral-vector-vaccine', source_citation = 'World Health Organization -- vaccine types; Ministry of Health and Family Welfare, Universal Immunisation Programme.', question_data = '{"craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "Live attenuated vaccines", "body_hi": "जीवित क्षीणीकृत टीके", "isCorrect": true}, {"id": "b", "body": "Inactivated whole-pathogen vaccines", "body_hi": "निष्क्रिय पूर्ण-रोगाणु टीके", "isCorrect": false}, {"id": "c", "body": "Toxoid vaccines", "body_hi": "टॉक्सॉइड टीके", "isCorrect": false}, {"id": "d", "body": "Non-replicating viral vector vaccines", "body_hi": "प्रतिकृति न बनाने वाले वायरल वेक्टर टीके", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'bi-viral-vector-vaccine' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Astronomy & Earth Science', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements:', body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 2 is correct. The Moon''s orbit is inclined about 5 degrees to the plane of the Earth''s orbit, so at most new and full moons the Moon passes above or below the line joining the Sun and the Earth; an eclipse happens only when a new or full moon falls near the points where the two orbits cross. Statement 1 is wrong: a lunar eclipse happens when the Earth comes between the Sun and the Moon, which is possible only at full moon; solar eclipses happen at new moon.', explanation_hi = 'केवल कथन 2 सही है। चंद्रमा की कक्षा पृथ्वी की कक्षा के तल से लगभग 5 अंश झुकी है, इसलिए अधिकांश अमावस्या और पूर्णिमा पर चंद्रमा सूर्य और पृथ्वी को जोड़ने वाली रेखा के ऊपर या नीचे से गुज़रता है; ग्रहण तभी होता है जब अमावस्या या पूर्णिमा उन बिंदुओं के पास पड़े जहाँ दोनों कक्षाएँ कटती हैं। कथन 1 गलत है: चंद्र ग्रहण तब होता है जब पृथ्वी सूर्य और चंद्रमा के बीच आती है, जो केवल पूर्णिमा को संभव है; सूर्य ग्रहण अमावस्या को होते हैं।', concept_group_id = 'as-eclipses-easy', source_citation = 'NASA -- Eclipses.', question_data = '{"statements": ["A lunar eclipse can happen only at new moon.", "Since the Moon''s orbit is tilted slightly to the Earth''s, the Sun, the Earth and the Moon do not line up at every new and full moon, so eclipses do not happen every month."], "statements_hi": ["चंद्र ग्रहण केवल अमावस्या को हो सकता है।", "चूँकि चंद्रमा की कक्षा पृथ्वी की कक्षा से थोड़ी झुकी है, इसलिए हर अमावस्या और पूर्णिमा को सूर्य, पृथ्वी और चंद्रमा एक रेखा में नहीं आते, और ग्रहण हर महीने नहीं होते।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'as-eclipses-easy' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Astronomy & Earth Science', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements:', body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. On the Earth, wind, water and moving plates soon erase most craters, but on the airless Moon a crater changes only when later impacts strike it -- which is why its surface is a record of the early solar system. Statement 2 is wrong: stars, like the Sun, produce their own light by nuclear fusion; it is planets and moons that shine by reflected light.', explanation_hi = 'केवल कथन 1 सही है। पृथ्वी पर हवा, पानी और खिसकती प्लेटें अधिकांश गड्ढों को जल्दी मिटा देती हैं, पर वायुरहित चंद्रमा पर गड्ढा तभी बदलता है जब बाद में कोई टक्कर उस पर पड़े; इसीलिए उसकी सतह आरंभिक सौरमंडल का अभिलेख है। कथन 2 गलत है: तारे, सूर्य की तरह, नाभिकीय संलयन से अपना प्रकाश उत्पन्न करते हैं; परावर्तित प्रकाश से ग्रह और चंद्रमा चमकते हैं।', concept_group_id = 'as-stars-moon-atmosphere-easy', source_citation = 'NCERT Class VIII Science (Stars and the Solar System); NASA.', question_data = '{"statements": ["Craters on the Moon stay sharp for billions of years because the Moon has almost no atmosphere, so no wind or rain wears them away.", "Stars shine by reflecting light from the Sun."], "statements_hi": ["चंद्रमा के गड्ढे अरबों वर्षों तक तीखे बने रहते हैं क्योंकि चंद्रमा पर लगभग कोई वायुमंडल नहीं है, इसलिए कोई हवा या वर्षा उन्हें घिसती नहीं।", "तारे सूर्य के प्रकाश को परावर्तित करके चमकते हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'as-stars-moon-atmosphere-easy' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Biology, Health & Biotechnology', type = 'statement_based', difficulty = 'easy', body = 'A child who rarely goes out in the sun has soft, weak bones and bowed legs. Consider the following statements:', body_hi = 'धूप में कम ही निकलने वाले एक बच्चे की हड्डियाँ नरम और कमज़ोर हैं तथा पैर टेढ़े हैं। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. The condition is rickets: without vitamin D the body cannot absorb enough calcium and phosphorus to harden growing bones. Sunlight on the skin makes vitamin D, which also comes from fish, eggs and fortified foods. Statement 2 is wrong: a lack of vitamin C causes scurvy, with bleeding gums and slow healing; extra vitamin C does not mend rickets.', explanation_hi = 'केवल कथन 1 सही है। यह स्थिति रिकेट्स है: विटामिन D के बिना शरीर बढ़ती हड्डियों को कठोर बनाने के लिए पर्याप्त कैल्शियम और फ़ॉस्फ़ोरस अवशोषित नहीं कर पाता। त्वचा पर धूप विटामिन D बनाती है, जो मछली, अंडों और पोषण-संवर्धित खाद्यों से भी मिलता है। कथन 2 गलत है: विटामिन C की कमी से स्कर्वी होता है, जिसमें मसूड़ों से खून आता है और घाव धीरे भरते हैं; अतिरिक्त विटामिन C रिकेट्स ठीक नहीं करता।', concept_group_id = 'bi-deficiency-diseases-easy', source_citation = 'NCERT Class VI Science (Components of Food).', question_data = '{"statements": ["The child is probably short of vitamin D, which the skin makes when exposed to sunlight.", "Giving the child more vitamin C would cure the condition."], "statements_hi": ["बच्चे में संभवतः विटामिन D की कमी है, जिसे त्वचा धूप के संपर्क में बनाती है।", "बच्चे को अधिक विटामिन C देने से यह स्थिति ठीक हो जाएगी।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "application"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'bi-deficiency-diseases-easy' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Biology, Health & Biotechnology', type = 'statement_based', difficulty = 'easy', body = 'A person''s pancreas stops making insulin. Consider the following statements:', body_hi = 'किसी व्यक्ति का अग्न्याशय इंसुलिन बनाना बंद कर देता है। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Neither statement is correct. Insulin lets the body''s cells take up glucose from the blood, so without it blood sugar rises -- type 1 diabetes, in which the pancreas''s insulin-making cells are destroyed. Insulin is a protein, so if swallowed it is broken down by digestive enzymes like any other protein; that is why it is injected, or in some newer forms inhaled.', explanation_hi = 'दोनों में से कोई कथन सही नहीं है। इंसुलिन शरीर की कोशिकाओं को रक्त से ग्लूकोज़ लेने देता है, इसलिए उसके बिना रक्त शर्करा बढ़ती है; यही टाइप 1 मधुमेह है, जिसमें अग्न्याशय की इंसुलिन बनाने वाली कोशिकाएँ नष्ट हो जाती हैं। इंसुलिन एक प्रोटीन है, इसलिए निगलने पर पाचक एंज़ाइम उसे किसी भी अन्य प्रोटीन की तरह तोड़ देते हैं; इसीलिए उसे इंजेक्शन से, या कुछ नए रूपों में साँस से, दिया जाता है।', concept_group_id = 'bi-rbc-insulin-easy', source_citation = 'NCERT Class X Science (Control and Coordination); NCERT Class XI Biology.', question_data = '{"statements": ["The level of sugar in the person''s blood will tend to fall.", "Insulin swallowed as a tablet would work as well as an injection."], "statements_hi": ["व्यक्ति के रक्त में शर्करा का स्तर घटने की प्रवृत्ति दिखाएगा।", "गोली के रूप में निगला गया इंसुलिन इंजेक्शन जितना ही काम करेगा।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'bi-rbc-insulin-easy' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Astronomy & Earth Science', type = 'statement_based', difficulty = 'medium', body = 'A star is 100 light-years away from the Earth. Consider the following statements:', body_hi = 'एक तारा पृथ्वी से 100 प्रकाश-वर्ष दूर है। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. A light-year is the distance light travels in a year, about 9.5 trillion km, so light from the star takes 100 years to reach us and we see it as it was a century ago; news of an explosion 50 years ago is still on its way and will arrive in another 50 years (statement 2). Statement 3 is the near-miss: the Sun is about 150 million km away, so its light takes about eight minutes, not hours, to reach us; the light of the nearest star, Proxima Centauri, is about 4.2 years old.', explanation_hi = 'केवल कथन 1 सही है। प्रकाश-वर्ष वह दूरी है जो प्रकाश एक वर्ष में तय करता है, लगभग 9.5 लाख करोड़ किमी, इसलिए तारे का प्रकाश हम तक पहुँचने में 100 वर्ष लेता है और हम उसे वैसा देखते हैं जैसा वह एक सदी पहले था; 50 वर्ष पहले के विस्फोट की ख़बर अभी रास्ते में है और 50 वर्ष बाद पहुँचेगी (कथन 2)। कथन 3 निकट-भ्रम है: सूर्य लगभग 15 करोड़ किमी दूर है, इसलिए उसका प्रकाश हम तक पहुँचने में लगभग आठ मिनट लेता है, घंटे नहीं; निकटतम तारे प्रॉक्सिमा सेंटॉरी का प्रकाश लगभग 4.2 वर्ष पुराना है।', concept_group_id = 'as-light-year-distances', source_citation = 'NCERT Class VIII Science (Stars and the Solar System).', question_data = '{"statements": ["The light we see from it today left the star about 100 years ago.", "If the star had exploded 50 years ago, we would already have seen the explosion.", "Sunlight reaching the Earth now left the Sun about eight hours ago."], "statements_hi": ["आज हम उसका जो प्रकाश देखते हैं वह तारे से लगभग 100 वर्ष पहले चला था।", "यदि तारा 50 वर्ष पहले फट गया होता, तो हम वह विस्फोट अब तक देख चुके होते।", "अभी पृथ्वी पर पहुँच रहा सूर्य का प्रकाश लगभग आठ घंटे पहले सूर्य से चला था।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "application"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'as-light-year-distances' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Astronomy & Earth Science', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about images of black holes:', body_hi = 'ब्लैक होल के चित्रों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct; both images came from the Event Horizon Telescope, which links radio dishes across the world into one Earth-sized telescope. Statement 3 is the near-miss: nothing, not even light, escapes from inside the event horizon, so the black hole itself is dark. The ring is radio light from gas heated to billions of degrees as it swirls just outside the horizon, and the dark centre is the black hole''s ''shadow''.', explanation_hi = 'कथन 1 और 2 सही हैं; दोनों चित्र इवेंट होराइज़न टेलीस्कोप से आए, जो संसार भर की रेडियो डिशों को जोड़कर पृथ्वी के आकार की एक दूरबीन बनाता है। कथन 3 निकट-भ्रम है: घटना क्षितिज के भीतर से कुछ भी, प्रकाश भी, नहीं निकल सकता, इसलिए स्वयं ब्लैक होल अंधकारमय है। वलय क्षितिज के ठीक बाहर घूमती अरबों अंश तक तपी गैस का रेडियो प्रकाश है, और अंधेरा केंद्र ब्लैक होल की ''छाया'' है।', concept_group_id = 'as-black-holes', source_citation = 'Event Horizon Telescope collaboration; NASA.', question_data = '{"statements": ["The first image of a black hole, released in 2019, showed the giant black hole at the centre of the galaxy M87.", "An image of Sagittarius A*, the black hole at the centre of the Milky Way, was released in 2022.", "The bright ring in these images is light given off by the black hole itself."], "statements_hi": ["2019 में जारी ब्लैक होल के पहले चित्र में आकाशगंगा M87 के केंद्र का विशाल ब्लैक होल दिखा।", "आकाशगंगा (मिल्की वे) के केंद्र के ब्लैक होल सैजिटेरियस A* का चित्र 2022 में जारी किया गया।", "इन चित्रों में दिखने वाला चमकीला वलय स्वयं ब्लैक होल द्वारा छोड़ा गया प्रकाश है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'as-black-holes' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Astronomy & Earth Science', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements:', body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 3 are correct. A Cepheid''s true brightness is tied to how fast it pulses, so two with the same period give out the same light; since apparent brightness falls with the square of distance, one that looks four times fainter is twice as far away -- the method Edwin Hubble used to show that other galaxies exist. Statement 2 is the near-miss: it is Cepheids that swell and shrink; a pulsar is a spinning neutron star whose beam of radiation sweeps past the Earth like a lighthouse. Nebulae such as the one in Orion are stellar nurseries; others, like the Crab Nebula, are the debris of exploded stars.', explanation_hi = 'कथन 1 और 3 सही हैं। सेफ़ीड की वास्तविक चमक उसके स्पंदन की गति से जुड़ी है, इसलिए एक ही अवधि वाले दो सेफ़ीड बराबर प्रकाश देते हैं; चूँकि दिखने वाली चमक दूरी के वर्ग के साथ घटती है, चार गुना धुँधला दिखने वाला दोगुनी दूरी पर है; इसी विधि से एडविन हबल ने दिखाया कि अन्य आकाशगंगाएँ हैं। कथन 2 निकट-भ्रम है: फूलते और सिकुड़ते सेफ़ीड हैं; पल्सर एक घूमता न्यूट्रॉन तारा है जिसकी विकिरण-किरण प्रकाशस्तंभ की तरह पृथ्वी के पास से गुज़रती है। ओरायन जैसी नीहारिकाएँ तारों की जन्मस्थली हैं; क्रैब नीहारिका जैसी अन्य फटे तारों का मलबा हैं।', concept_group_id = 'as-cepheids-pulsars-nebulae', source_citation = 'NASA -- Science (solar system, universe and exoplanet pages).', question_data = '{"statements": ["Two Cepheid variable stars pulse with the same period, but one looks four times fainter than the other; it is therefore about twice as far away.", "A pulsar''s regular pulses arise because the star swells and shrinks.", "A nebula is a cloud of gas and dust in which new stars can form."], "statements_hi": ["दो सेफ़ीड परिवर्ती तारे एक ही अवधि से स्पंदित होते हैं, पर एक दूसरे से चार गुना धुँधला दिखता है; इसलिए वह लगभग दोगुनी दूरी पर है।", "पल्सर के नियमित स्पंदन इसलिए होते हैं क्योंकि तारा फूलता और सिकुड़ता है।", "नीहारिका गैस और धूल का एक बादल है जिसमें नए तारे बन सकते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "application"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'as-cepheids-pulsars-nebulae' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Astronomy & Earth Science', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the universe:', body_hi = 'ब्रह्मांड के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 3 are correct. If only visible matter were present, stars far from a galaxy''s centre should orbit more slowly, as the outer planets do round the Sun; instead their speeds stay high, implying unseen mass that gives out no light -- dark matter, about five times as abundant as ordinary matter. The cosmic microwave background, discovered in 1965, is radiation released about 380,000 years after the Big Bang and since stretched to microwave wavelengths by expansion. Statement 2 is wrong: dark energy is the unknown cause of the accelerating expansion of the universe, about 70 per cent of its energy.', explanation_hi = 'कथन 1 और 3 सही हैं। यदि केवल दृश्य पदार्थ होता, तो आकाशगंगा के केंद्र से दूर के तारे धीमे घूमते, जैसे सूर्य के बाहरी ग्रह घूमते हैं; इसके बजाय उनकी गति ऊँची बनी रहती है, जो ऐसे अदृश्य द्रव्यमान का संकेत है जो कोई प्रकाश नहीं देता, यही डार्क मैटर है, जो सामान्य पदार्थ से लगभग पाँच गुना अधिक है। 1965 में खोजी गई कॉस्मिक माइक्रोवेव पृष्ठभूमि बिग बैंग के लगभग 3.8 लाख वर्ष बाद छोड़ा गया विकिरण है, जो तब से विस्तार के कारण माइक्रोवेव तरंगदैर्घ्य तक खिंच गया है। कथन 2 गलत है: डार्क एनर्जी ब्रह्मांड के त्वरित विस्तार का अज्ञात कारण है, जो उसकी ऊर्जा का लगभग 70 प्रतिशत है।', concept_group_id = 'as-dark-matter-cmb', source_citation = 'NASA -- Science (solar system, universe and exoplanet pages).', question_data = '{"statements": ["Stars in the outer parts of galaxies orbit so fast that the visible matter alone could not hold them, which is one of the main pieces of evidence for dark matter.", "Dark energy is the energy released by black holes as they swallow stars.", "The cosmic microwave background is the faint afterglow of the hot early universe, reaching us from every direction."], "statements_hi": ["आकाशगंगाओं के बाहरी भागों के तारे इतनी तेज़ी से परिक्रमा करते हैं कि केवल दृश्य पदार्थ उन्हें थाम नहीं सकता, जो डार्क मैटर के मुख्य प्रमाणों में से एक है।", "डार्क एनर्जी वह ऊर्जा है जो ब्लैक होल तारों को निगलते समय छोड़ते हैं।", "कॉस्मिक माइक्रोवेव पृष्ठभूमि गर्म आरंभिक ब्रह्मांड की धुँधली परवर्ती चमक है, जो हम तक हर दिशा से पहुँचती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'as-dark-matter-cmb' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Astronomy & Earth Science', type = 'statement_based', difficulty = 'hard', body = 'Consider the following statements about exoplanets:', body_hi = 'बाह्यग्रहों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct: missions such as Kepler and TESS have found thousands of planets this way. Statement 2 is the near-miss: Hubble circles the Earth a few hundred kilometres up, but Webb orbits the Sun near the second Lagrange point, L2, about 1.5 million km from the Earth on the side away from the Sun, where its sunshield keeps its infrared instruments cold. Statement 3 is wrong: planets are billions of times fainter than their stars, so direct images are rare; most are found by transits or by the wobble they cause in their star.', explanation_hi = 'केवल कथन 1 सही है: केप्लर और TESS जैसे अभियानों ने इस तरह हज़ारों ग्रह खोजे हैं। कथन 2 निकट-भ्रम है: हबल कुछ सौ किलोमीटर ऊपर पृथ्वी की परिक्रमा करती है, पर वेब सूर्य से दूर की ओर पृथ्वी से लगभग 15 लाख किमी पर दूसरे लाग्रांज बिंदु L2 के पास सूर्य की परिक्रमा करती है, जहाँ उसकी सूर्य-ढाल उसके अवरक्त उपकरणों को ठंडा रखती है। कथन 3 गलत है: ग्रह अपने तारों से अरबों गुना धुँधले होते हैं, इसलिए सीधे चित्र दुर्लभ हैं; अधिकांश पारगमन से या अपने तारे में उत्पन्न डगमगाहट से खोजे जाते हैं।', concept_group_id = 'as-exoplanets-jwst', source_citation = 'NASA -- James Webb Space Telescope; NASA Exoplanet Archive.', question_data = '{"statements": ["The transit method finds planets from the small dip in a star''s brightness as a planet passes in front of it.", "The James Webb Space Telescope orbits the Earth, as the Hubble Space Telescope does.", "Most known exoplanets have been found by photographing them directly."], "statements_hi": ["पारगमन विधि किसी ग्रह के तारे के सामने से गुज़रने पर तारे की चमक में आई छोटी गिरावट से ग्रह खोजती है।", "जेम्स वेब अंतरिक्ष दूरबीन हबल अंतरिक्ष दूरबीन की तरह पृथ्वी की परिक्रमा करती है।", "अधिकांश ज्ञात बाह्यग्रह उनका सीधे चित्र लेकर खोजे गए हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'as-exoplanets-jwst' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Astronomy & Earth Science', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about small bodies of the solar system:', body_hi = 'सौरमंडल के छोटे पिंडों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1, 3 and 4 are correct. Statement 2 is the near-miss: a meteoroid is the rock in space, a meteor is the streak of light it makes as it burns up in the air -- a ''shooting star'' -- and a meteorite is the part that reaches the ground. A comet''s tails are pushed away from the Sun by sunlight and the solar wind, so a comet moving outward travels tail first. The Kuiper Belt, home of Pluto, and the more distant Oort Cloud are the sources of most comets.', explanation_hi = 'कथन 1, 3 और 4 सही हैं। कथन 2 निकट-भ्रम है: उल्कापिंड (मीटियोरॉयड) अंतरिक्ष में चट्टान है, उल्का (मीटियोर) वह प्रकाश-रेखा है जो वह हवा में जलते हुए बनाता है, यानी ''टूटता तारा'', और उल्कापिंड का भूमि तक पहुँचने वाला भाग उल्काश्म (मीटियोराइट) है। धूमकेतु की पूँछें सूर्य के प्रकाश और सौर पवन से सूर्य से दूर धकेली जाती हैं, इसलिए बाहर जाता धूमकेतु पूँछ आगे करके चलता है। प्लूटो का घर काइपर बेल्ट और उससे दूर का ऊर्ट बादल अधिकांश धूमकेतुओं के स्रोत हैं।', concept_group_id = 'as-small-bodies', source_citation = 'NASA -- Science (solar system, universe and exoplanet pages).', question_data = '{"statements": ["Most asteroids are found between the orbits of Mars and Jupiter.", "A meteor is a piece of space rock that survives its fall through the atmosphere and reaches the ground.", "A comet''s tail points away from the Sun.", "The Kuiper Belt lies beyond the orbit of Neptune."], "statements_hi": ["अधिकांश क्षुद्रग्रह मंगल और बृहस्पति की कक्षाओं के बीच पाए जाते हैं।", "उल्का अंतरिक्ष चट्टान का वह टुकड़ा है जो वायुमंडल से गिरते हुए बच जाता है और भूमि तक पहुँचता है।", "धूमकेतु की पूँछ सूर्य से दूर की ओर रहती है।", "काइपर बेल्ट नेपच्यून की कक्षा से परे स्थित है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": true}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'as-small-bodies' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Biology, Health & Biotechnology', type = 'statement_based', difficulty = 'hard', body = 'Consider the following statements about stem cells:', body_hi = 'स्टेम कोशिकाओं के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'All three statements are correct. Shinya Yamanaka showed in 2006 that switching on four genes turns skin cells into cells that behave like embryonic ones, which won him a Nobel Prize in 2012. Statement 2 states the distinction students often miss: embryonic stem cells are pluripotent, while adult stem cells such as those of the bone marrow are multipotent, limited to the cell types of their own tissue. Cord blood, rich in blood-forming stem cells, is banked and used to treat leukaemia and inherited blood disorders.', explanation_hi = 'तीनों कथन सही हैं। शिन्या यामानाका ने 2006 में दिखाया कि चार जीन सक्रिय करने से त्वचा कोशिकाएँ भ्रूणीय कोशिकाओं जैसा व्यवहार करने लगती हैं, जिसके लिए उन्हें 2012 में नोबेल पुरस्कार मिला। कथन 2 वह भेद बताता है जो विद्यार्थी प्रायः चूकते हैं: भ्रूणीय स्टेम कोशिकाएँ बहुशक्त (प्लूरिपोटेंट) हैं, जबकि अस्थि मज्जा जैसी वयस्क स्टेम कोशिकाएँ बहुक्षम (मल्टीपोटेंट) हैं, जो अपने ही ऊतक की कोशिकाओं तक सीमित हैं। रक्त-निर्माता स्टेम कोशिकाओं से भरपूर गर्भनाल रक्त बैंकों में रखा जाता है और ल्यूकेमिया तथा आनुवंशिक रक्त विकारों के उपचार में प्रयुक्त होता है।', concept_group_id = 'bi-stem-cells', source_citation = 'Indian Council of Medical Research -- National Guidelines for Stem Cell Research, 2017.', question_data = '{"statements": ["Induced pluripotent stem cells are made by reprogramming ordinary adult cells.", "Embryonic stem cells can form almost any cell type of the body, while the blood-forming stem cells of the bone marrow give rise mainly to blood cells.", "Umbilical cord blood is a source of blood-forming stem cells."], "statements_hi": ["प्रेरित बहुशक्त (इंड्यूस्ड प्लूरिपोटेंट) स्टेम कोशिकाएँ सामान्य वयस्क कोशिकाओं को पुनः क्रमादेशित करके बनाई जाती हैं।", "भ्रूणीय स्टेम कोशिकाएँ शरीर की लगभग किसी भी प्रकार की कोशिका बना सकती हैं, जबकि अस्थि मज्जा की रक्त-निर्माता स्टेम कोशिकाएँ मुख्यतः रक्त कोशिकाएँ बनाती हैं।", "गर्भनाल रक्त रक्त-निर्माता स्टेम कोशिकाओं का एक स्रोत है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'bi-stem-cells' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Biology, Health & Biotechnology', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about viruses:', body_hi = 'वायरसों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 2 is correct. Viruses with RNA genomes such as influenza copy their genes without the proof-reading that cells use for DNA, so they change quickly; the flu virus''s surface proteins drift enough each year for the WHO to recommend new vaccine strains. Statement 1 is wrong: outside a host cell a virus is inert, which is why viruses are said to lie on the border of the living and the non-living. Statement 3 is wrong: most viruses are tens of times smaller than a bacterium and can be seen only with an electron microscope.', explanation_hi = 'केवल कथन 2 सही है। इन्फ़्लुएंज़ा जैसे RNA जीनोम वाले वायरस अपने जीनों की प्रतिलिपि उस प्रूफ़-रीडिंग के बिना बनाते हैं जो कोशिकाएँ DNA के लिए करती हैं, इसलिए वे जल्दी बदलते हैं; फ़्लू वायरस के सतही प्रोटीन हर वर्ष इतना बदल जाते हैं कि WHO नए टीका-स्ट्रेन की सिफ़ारिश करता है। कथन 1 गलत है: पोषी कोशिका के बाहर वायरस निष्क्रिय रहता है, इसीलिए वायरसों को सजीव और निर्जीव की सीमा पर कहा जाता है। कथन 3 गलत है: अधिकांश वायरस जीवाणु से दसियों गुना छोटे होते हैं और केवल इलेक्ट्रॉन सूक्ष्मदर्शी से दिखते हैं।', concept_group_id = 'bi-viruses', source_citation = 'NCERT Class XI Biology (Biological Classification); World Health Organization -- influenza vaccine composition.', question_data = '{"statements": ["Viruses can multiply on their own in water or soil, outside any living cell.", "Many viruses, such as influenza, have RNA as their genetic material, which is copied with many errors; their fast mutation is one reason flu vaccines are updated every year.", "Viruses are larger than most bacteria."], "statements_hi": ["वायरस किसी भी जीवित कोशिका के बाहर, पानी या मिट्टी में, अपने आप गुणन कर सकते हैं।", "इन्फ़्लुएंज़ा जैसे अनेक वायरसों का आनुवंशिक पदार्थ RNA है, जिसकी प्रतिलिपि में बहुत त्रुटियाँ होती हैं; उनका तेज़ उत्परिवर्तन एक कारण है कि फ़्लू के टीके हर वर्ष अद्यतन किए जाते हैं।", "वायरस अधिकांश जीवाणुओं से बड़े होते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'bi-viruses' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Biology, Health & Biotechnology', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the Wolbachia method of controlling dengue:', body_hi = 'डेंगू नियंत्रण की वोल्बाकिया विधि के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. Wolbachia, a bacterium found naturally in many insects, blocks dengue, Zika and chikungunya viruses from multiplying inside the mosquito. When an infected male mates with an uninfected female her eggs fail to hatch, while infected females produce infected young whatever the male -- so the bacterium spreads by itself until most mosquitoes carry it. Statement 3 is wrong: the method replaces the population with one that transmits less, rather than wiping mosquitoes out; the ICMR''s Vector Control Research Centre has developed Wolbachia-carrying Aedes strains for use in India.', explanation_hi = 'कथन 1 और 2 सही हैं। अनेक कीटों में प्राकृतिक रूप से पाया जाने वाला जीवाणु वोल्बाकिया डेंगू, ज़ीका और चिकनगुनिया वायरसों को मच्छर के भीतर गुणन करने से रोकता है। संक्रमित नर के असंक्रमित मादा से मिलने पर उसके अंडे नहीं फूटते, जबकि संक्रमित मादाएँ नर कोई भी हो, संक्रमित संतान देती हैं; इसलिए जीवाणु अपने आप तब तक फैलता है जब तक अधिकांश मच्छर उसे धारण न कर लें। कथन 3 गलत है: यह विधि मच्छरों को मिटाने के बजाय आबादी को कम संक्रमण फैलाने वाली आबादी से बदल देती है; ICMR के वेक्टर नियंत्रण अनुसंधान केंद्र ने भारत में उपयोग के लिए वोल्बाकिया-धारी एडीज़ स्ट्रेन विकसित किए हैं।', concept_group_id = 'bi-wolbachia', source_citation = 'Indian Council of Medical Research -- Vector Control Research Centre; World Health Organization.', question_data = '{"statements": ["Aedes mosquitoes carrying Wolbachia are less able to transmit viruses such as dengue.", "Once released, Wolbachia spreads through the wild mosquito population on its own, because infected females pass the bacterium to all their offspring.", "The method works by killing all the mosquitoes in the area where they are released."], "statements_hi": ["वोल्बाकिया धारण करने वाले एडीज़ मच्छर डेंगू जैसे वायरसों को फैलाने में कम सक्षम होते हैं।", "छोड़े जाने के बाद वोल्बाकिया जंगली मच्छरों में अपने आप फैल जाता है, क्योंकि संक्रमित मादाएँ यह जीवाणु अपनी सभी संतानों को देती हैं।", "यह विधि उस क्षेत्र के सभी मच्छरों को मारकर काम करती है जहाँ उन्हें छोड़ा जाता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'bi-wolbachia' returning concept_group_id;
